ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| case {
    ImageFileName=/\\(powershell|pwsh)\.exe$/i AND regex("Set-MpPreference|Add-MpPreference|DisableRealtimeMonitoring|DisableBehaviorMonitoring|ExclusionPath|ExclusionExtension|Uninstall-WindowsFeature.*Windows-Defender", field=CommandLine, flags="i") | bucket:="defender_off" ;
    ImageFileName=/\\(sc|net|net1|taskkill|powershell|pwsh)\.exe$/i AND regex("VeeamBackupSvc|VeeamDeploymentService|VeeamTransportSvc|VeeamNFSSvc|MSSQLSERVER|SQLAgent|SQLWriter|MSExchange|BackupExec|Acronis|CommVault|Veritas|NetBackup", field=CommandLine, flags="i") AND regex("stop|kill|/F|Stop-Service", field=CommandLine, flags="i") | bucket:="backup_kill" ;
    * | bucket:="drop"
  }
| bucket != "drop"
| groupBy([aid, ComputerName, UserName], function={ collect([bucket, ImageFileName, CommandLine]) | count(field=bucket, distinct=true, as=bucket_types) })
| bucket_types >= 2
